import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"« Fuse Group » (Groupe de protection) pour Zendure HA","description":"« Fuse Group » et limites de puissance dans l'intégration Zendure pour Home Assistant.","frontmatter":{"title":"« Fuse Group » (Groupe de protection) pour Zendure HA","description":"« Fuse Group » et limites de puissance dans l'intégration Zendure pour Home Assistant."},"headers":[],"relativePath":"fr/collection/zendure-ha/fuse-group.md","filePath":"fr/collection/zendure-ha/fuse-group.md","lastUpdated":1793123188000}`),o={name:"fr/collection/zendure-ha/fuse-group.md"};function d(n,e,u,s,c,p){return r(),i("div",null,[...e[0]||(e[0]=[a('<p><a id="zendure-ha-fuse-group"></a><a id="orientation-actuelle"></a></p><h1 id="fuse-group" tabindex="-1">Fuse Group <a class="header-anchor" href="#fuse-group" aria-label="Permalink to &quot;Fuse Group {#fuse-group}&quot;">​</a></h1><p>Le « Fuse Group » est un regroupement lié à la sécurité et au contrôle. Il indique quels appareils Zendure sont raccordés au même fusible (ou au même circuit électrique) et définit la puissance maximale autorisée sur ce circuit.</p><div class="danger custom-block"><p class="custom-block-title">Responsabilité</p><p>Le choix correct du « Fuse Group » est crucial pour la sécurité. Choisissez-la en fonction de votre installation électrique et des réglementations locales.</p></div><h2 id="warum-sie-wichtig-ist" tabindex="-1">Pourquoi est-ce important ? <a class="header-anchor" href="#warum-sie-wichtig-ist" aria-label="Permalink to &quot;Pourquoi est-ce important ? {#warum-sie-wichtig-ist}&quot;">​</a></h2><p>Le Zendure Manager répartit la puissance en se basant sur le paramètre « Fuse Group » (groupe de protection). La somme des puissances des appareils appartenant à un même groupe ne doit pas dépasser la limite définie.</p><p>Si aucun « Fuse Group » approprié n&#39;est défini, l&#39;appareil ne sera pas pris en compte pour les fonctionnalités intelligentes.</p><h2 id="typische-optionen" tabindex="-1">Options courantes <a class="header-anchor" href="#typische-optionen" aria-label="Permalink to &quot;Options courantes {#typische-optionen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Signification</th></tr></thead><tbody><tr><td><code>Nicht verwendet</code></td><td>L&#39;appareil n&#39;est associé à aucun « Fuse Group » et n&#39;est pas utilisé pour la gestion intelligente</td></tr><tr><td><code>Eigener Stromkreis / eigene Phase</code></td><td>L&#39;appareil est seul sur son propre circuit électrique</td></tr><tr><td><code>Sicherungsgruppe max. 800 W</code></td><td>Groupe avec une limite maximale de 800 W</td></tr><tr><td><code>Sicherungsgruppe max. 1200 W</code></td><td>Groupe avec une limite maximale de 1200 W</td></tr><tr><td><code>Sicherungsgruppe max. 2000 W</code></td><td>Groupe avec une limite maximale de 2000 W</td></tr><tr><td><code>Sicherungsgruppe max. 2400 W</code></td><td>Groupe avec une limite maximale de 2400 W</td></tr><tr><td><code>Sicherungsgruppe max. 3600 W</code></td><td>Groupe avec une limite maximale de 3600 W</td></tr><tr><td><code>Sicherungsgruppe max. 4000 W</code></td><td>Groupe avec une limite maximale de 4000 W</td></tr><tr><td><code>Sicherungsgruppe max. 5000 W</code></td><td>Groupe avec une limite maximale de 5000 W</td></tr></tbody></table><h2 id="verbindungstatus" tabindex="-1">État de la connexion <a class="header-anchor" href="#verbindungstatus" aria-label="Permalink to &quot;État de la connexion {#verbindungstatus}&quot;">​</a></h2><p>L&#39;intégration affiche un état de connexion qui aide à situer la situation :</p><table tabindex="0"><thead><tr><th>État</th><th>Signification</th></tr></thead><tbody><tr><td><code>Unbekannt</code></td><td>Aucun état de connexion défini</td></tr><tr><td><code>Kalibrierung</code></td><td>Appareil calibré</td></tr><tr><td><code>HEMS</code></td><td>Appareil contrôlé par le HEMS</td></tr><tr><td><code>Keine Sicherungsgruppe</code></td><td>Groupe de fusibles (Fuse Group) manquant</td></tr><tr><td><code>Verbunden (Cloud)</code></td><td>Connexion via le cloud</td></tr><tr><td><code>Verbunden (Local)</code></td><td>Connexion via MQTT local</td></tr><tr><td><code>Verbunden (zenSDK)</code></td><td>Connexion via zenSDK</td></tr></tbody></table><p>Wiki original :</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Fuse-Group" target="_blank" rel="noreferrer">Groupe de fusibles (Fuse Group)</a></li></ul>',14)])])}const h=t(o,[["render",d]]);export{m as __pageData,h as default};
